mapper.select:
SELECT t.id, t.dishware_id AS dishwareId, t.from_shop_type AS fromShopType, t.to_shop_type AS toShopType, t.quantity, t.unit_price AS unitPrice, t.total_price AS totalPrice, t.transfer_date AS transferDate, t.record_type AS recordType, t.related_record_id AS relatedRecordId, t.recorded_by AS recordedBy, i.code_number AS codeNumber, i.product_name AS productName, fr.name AS fromRestaurantName, tr.name AS toRestaurantName FROM dishware_transfer_records t LEFT JOIN dishware_info i ON i.id = t.dishware_id LEFT JOIN dishware_restaurant_locations fr ON fr.id = t.from_restaurant_id LEFT JOIN dishware_restaurant_locations tr ON tr.id = t.to_restaurant_id WHERE 1 = 1
AND ( (t.record_type = 'out' AND LOWER(t.from_shop_type) = LOWER(#{shopType})) OR (t.record_type = 'in' AND LOWER(t.to_shop_type) = LOWER(#{shopType})) )
AND t.transfer_date >= #{startDate}
AND t.transfer_date <= #{endDate}
ORDER BY t.transfer_date DESC, t.id DESC
